From a7dfe441892e270e7281a07513369a345b2c103a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:51:36 +0100
Subject: [PATCH] applets/taskmanager: minimize last active window behind
 Plasma popups

Opening Kickoff or another Plasma popup takes focus from the active
window, so clicking its task activated it again instead of minimizing
it. Treat it as still active then, and close the popup after minimizing.

BUG: 463836
---
 applets/taskmanager/CMakeLists.txt        |  1 +
 applets/taskmanager/backend.cpp           | 24 +++++++++++++++++++++++
 applets/taskmanager/backend.h             |  3 +++
 applets/taskmanager/qml/code/TaskTools.js |  8 +++++++-
 applets/taskmanager/qml/main.qml          |  9 +++++++++
 5 files changed, 44 insertions(+), 1 deletion(-)

diff --git a/applets/taskmanager/CMakeLists.txt b/applets/taskmanager/CMakeLists.txt
index 64f548de35..f020197548 100644
--- a/applets/taskmanager/CMakeLists.txt
+++ b/applets/taskmanager/CMakeLists.txt
@@ -47,6 +47,7 @@ target_link_libraries(org.kde.plasma.taskmanager PRIVATE
                       Qt::Quick
                       Plasma::Activities
                       Plasma::ActivitiesStats
+                      Plasma::PlasmaQuick
                       KF6::ConfigGui
                       KF6::GlobalAccel
                       KF6::I18n
diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..fee70658de 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -44,6 +44,9 @@
 #include <PlasmaActivities/Stats/ResultSet>
 #include <PlasmaActivities/Stats/Terms>

+#include <PlasmaQuick/Dialog>
+#include <PlasmaQuick/PopupPlasmaWindow>
+
 #include <processcore/process.h>
 #include <processcore/processes.h>

@@ -525,6 +528,27 @@ QRect Backend::globalRect(QQuickItem *item) const
     return iconRect;
 }

+static QWindow *focusedPlasmaPopup()
+{
+    QWindow *window = QGuiApplication::focusWindow();
+    if (qobject_cast<PlasmaQuick::PopupPlasmaWindow *>(window) || qobject_cast<PlasmaQuick::Dialog *>(window)) {
+        return window;
+    }
+    return nullptr;
+}
+
+bool Backend::isPlasmaPopupFocused() const
+{
+    return focusedPlasmaPopup();
+}
+
+void Backend::closeFocusedPlasmaPopup() const
+{
+    if (QWindow *popup = focusedPlasmaPopup()) {
+        popup->setVisible(false);
+    }
+}
+
 bool Backend::isApplication(const QUrl &url) const
 {
     if (!url.isValid() || !url.isLocalFile()) {
diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..366f87a80a 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -63,6 +63,9 @@ public:

     Q_INVOKABLE bool isApplication(const QUrl &url) const;

+    Q_INVOKABLE bool isPlasmaPopupFocused() const;
+    Q_INVOKABLE void closeFocusedPlasmaPopup() const;
+
     Q_INVOKABLE qint64 parentPid(qint64 pid) const;

     Q_INVOKABLE static QUrl tryDecodeApplicationsUrl(const QUrl &launcherUrl);
diff --git a/applets/taskmanager/qml/code/TaskTools.js b/applets/taskmanager/qml/code/TaskTools.js
index 8f8adadd6f..e90ed6020d 100644
--- a/applets/taskmanager/qml/code/TaskTools.js
+++ b/applets/taskmanager/qml/code/TaskTools.js
@@ -207,11 +207,17 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView
             }
         }
     } else {
+        // A focused Plasma popup such as Kickoff doesn't make the window that was active before it any less active
+        const activeBehindPopup = !tasks.tasksModel.activeTask.valid && model.WinIdList[0] === tasks.lastActiveWinId && tasks.backend.isPlasmaPopupFocused();
+
         if (model.IsMinimized) {
             tasks.tasksModel.requestToggleMinimized(index);
             tasks.tasksModel.requestActivate(index);
-        } else if (model.IsActive && plasmoid.configuration.minimizeActiveTaskOnClick) {
+        } else if ((model.IsActive || activeBehindPopup) && plasmoid.configuration.minimizeActiveTaskOnClick) {
             tasks.tasksModel.requestToggleMinimized(index);
+            if (activeBehindPopup) {
+                tasks.backend.closeFocusedPlasmaPopup();
+            }
         } else {
             tasks.tasksModel.requestActivate(index);
         }
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..df44fe6047 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -89,6 +89,7 @@ PlasmoidItem {

     property Item dragSource
     property var hoveredWinIds
+    property var lastActiveWinId

     signal requestLayout

@@ -169,6 +170,12 @@ PlasmoidItem {
         filterByActivity: Plasmoid.configuration.showOnlyCurrentActivity
         filterNotMinimized: Plasmoid.configuration.showOnlyMinimized

+        onActiveTaskChanged: {
+            if (activeTask.valid) {
+                tasks.lastActiveWinId = data(activeTask, TaskManager.AbstractTasksModel.WinIdList)[0];
+            }
+        }
+
         hideActivatedLaunchers: tasks.iconsOnly || Plasmoid.configuration.hideLauncherOnStart
         sortMode: sortModeEnumValue(Plasmoid.configuration.sortingStrategy)
         launchInPlace: tasks.iconsOnly && Plasmoid.configuration.sortingStrategy === 1
@@ -326,11 +333,13 @@ PlasmoidItem {

         TaskManager.VirtualDesktopInfo {
             id: virtualDesktopInfo
+            onCurrentDesktopChanged: tasks.lastActiveWinId = undefined
         }

         TaskManager.ActivityInfo {
             id: activityInfo
             readonly property string nullUuid: "00000000-0000-0000-0000-000000000000"
+            onCurrentActivityChanged: tasks.lastActiveWinId = undefined
         }

         Loader {
